/**
 * PuniCodex — Merchant Center feed contract tests.
 *
 * The feed (store/merchant-feed.xml.gz, generated by
 * scripts/generate-merchant-feed.js) is what Google Merchant Center actually
 * reads. The 2026-11 complaint — "Google doesn't register all the items" —
 * traced to the first-generation feed: one item per product with no
 * size/colour, which Google disapproves for apparel. These tests lock the
 * variant-level structure in:
 *
 *   1. gz decompresses to valid RSS 2.0 with the g: namespace.
 *   2. One <item> per purchasable variant; unsynced products (checkout would
 *      reject them) are excluded.
 *   3. Every item carries the required attributes, https absolute links, and
 *      a price matching the PDP's displayed price (from-price policy).
 *   4. Apparel variants carry g:color + g:size and group under
 *      g:item_group_id.
 *   5. build() is deterministic (byte-identical gzip across runs).
 *
 * Run standalone: node test/merchant-feed.test.js
 */

const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const root = path.join(__dirname, '..');
const CATALOG = require(path.join(root, 'store', 'products.json'));
const { build, feedPriceCents, feedId } = require(
  path.join(root, 'scripts', 'generate-merchant-feed.js')
);

const FEED = path.join(root, 'store', 'merchant-feed.xml.gz');

let passed = 0;
let failed = 0;
function test(name, fn) {
  try {
    fn();
    passed++;
    console.log(`  ✓ ${name}`);
  } catch (err) {
    failed++;
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
  }
}

const APPAREL = new Set(['tee', 'hoodie', 'crewneck', 'cap']);
// Kinds whose Printful variant labels carry a real size dimension (caps are
// colour-only one-size).
const SIZED = new Set(['tee', 'hoodie', 'crewneck']);
const REQUIRED = [
  'g:id',
  'g:title',
  'g:description',
  'g:link',
  'g:image_link',
  'g:condition',
  'g:availability',
  'g:price',
  'g:brand',
  'g:identifier_exists',
  'g:google_product_category',
];

function parseItems(xml) {
  return [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map((m) => m[1]);
}
function field(item, tag) {
  const m = item.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`));
  return m ? m[1] : null;
}

test('feed file exists, decompresses, and parses as RSS with the g: namespace', () => {
  assert.ok(fs.existsSync(FEED), 'store/merchant-feed.xml.gz missing — run generate-merchant-feed');
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  assert.ok(xml.startsWith('<?xml'), 'missing XML declaration');
  assert.ok(
    /<rss[^>]*xmlns:g="http:\/\/base\.google\.com\/ns\/1\.0"/.test(xml),
    'missing g: namespace'
  );
  assert.ok(xml.includes('<channel>') && xml.includes('</channel>'), 'malformed channel');
  const items = parseItems(xml);
  assert.ok(items.length > 100_000, `expected 100k+ variant items, got ${items.length}`);
});

test('one item per purchasable variant; unsynced products excluded', () => {
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  const items = parseItems(xml);
  let expected = 0;
  const syncedIds = new Set();
  for (const p of CATALOG.products) {
    if (!p.printfulProductId) continue;
    syncedIds.add(p.id);
    expected += Math.max(1, Object.keys(p.printfulVariants || {}).length);
  }
  assert.strictEqual(items.length, expected, `feed item count ${items.length} != ${expected}`);
  const unsynced = CATALOG.products.filter((p) => !p.printfulProductId).map((p) => p.id);
  assert.ok(unsynced.length > 0, 'fixture: expected at least one unsynced product');
  for (const id of unsynced) {
    assert.ok(!xml.includes(`<g:item_group_id>${id}</g:item_group_id>`), `${id} must be absent`);
  }
});

test('every item carries the required attributes with https absolute links', () => {
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  const items = parseItems(xml);
  for (const item of items) {
    const id = field(item, 'g:id') || '(no id)';
    for (const tag of REQUIRED) {
      const v = field(item, tag);
      assert.ok(v && v.trim().length > 0, `${id}: missing <${tag}>`);
    }
    for (const tag of ['g:link', 'g:image_link']) {
      const v = field(item, tag);
      assert.ok(/^https:\/\//.test(v), `${id}: <${tag}> not https absolute (${v})`);
    }
    assert.ok(/^\d+\.\d{2} USD$/.test(field(item, 'g:price')), `${id}: bad price`);
    assert.strictEqual(field(item, 'g:condition'), 'new');
    assert.strictEqual(field(item, 'g:availability'), 'in_stock');
  }
});

test('price matches the PDP displayed price (from-price policy)', () => {
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  const byGroup = new Map();
  for (const item of parseItems(xml)) {
    const group = field(item, 'g:item_group_id');
    if (!byGroup.has(group)) byGroup.set(group, []);
    byGroup.get(group).push(field(item, 'g:price'));
  }
  for (const p of CATALOG.products) {
    if (!p.printfulProductId) continue;
    const expected = `${(feedPriceCents(p) / 100).toFixed(2)} USD`;
    const prices = byGroup.get(p.id);
    assert.ok(prices && prices.length > 0, `${p.id}: no feed items`);
    for (const price of prices) assert.strictEqual(price, expected, `${p.id}: price mismatch`);
  }
});

test('apparel variants carry color + size and group under item_group_id', () => {
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  const items = parseItems(xml);
  let apparelChecked = 0;
  for (const item of items) {
    const group = field(item, 'g:item_group_id') || '';
    const kind = group.split('-').pop();
    if (!APPAREL.has(kind)) continue;
    apparelChecked++;
    assert.ok(field(item, 'g:color'), `${group}: apparel variant missing g:color`);
    if (SIZED.has(kind)) {
      assert.ok(field(item, 'g:size'), `${group}: sized apparel variant missing g:size`);
    }
  }
  assert.ok(apparelChecked > 20_000, `expected 20k+ apparel variants, got ${apparelChecked}`);
});

test('build() is deterministic (byte-identical gzip across runs)', () => {
  const a = build();
  const b = build();
  assert.strictEqual(a.items, b.items);
  assert.ok(a.buf.equals(b.buf), 'regenerating the feed changed its bytes');
});

test('feed links resolve to real product pages', () => {
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  const checked = new Set();
  for (const item of parseItems(xml)) {
    const link = field(item, 'g:link');
    const rel = link.replace('https://punicodex.com', '');
    if (checked.has(rel) || checked.size >= 2500) continue;
    checked.add(rel);
    assert.ok(
      fs.existsSync(path.join(root, rel, 'index.html')) || fs.existsSync(path.join(root, rel)),
      `${rel}: feed link has no page on disk`
    );
  }
  assert.ok(checked.size >= 2000, `expected 2000+ distinct product links, got ${checked.size}`);
});

test('g:id values are within Merchant Center limits and unique', () => {
  const xml = zlib.gunzipSync(fs.readFileSync(FEED)).toString('utf8');
  const ids = parseItems(xml).map((item) => field(item, 'g:id'));
  const seen = new Set();
  for (const id of ids) {
    assert.ok(id.length <= 50, `${id}: g:id longer than 50 chars (${id.length})`);
    assert.ok(!seen.has(id), `${id}: duplicate g:id`);
    seen.add(id);
  }
  // Deterministic shortening: same input → same shortened id, ≤50 chars.
  const long = 'huitzilopochtli-phonecase__Glossy_iPhone_11_Pro_Max';
  assert.strictEqual(feedId(long), feedId(long));
  assert.ok(feedId(long).length <= 50);
});

console.log(`\nMerchant Feed: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
